import java.io.InputStream;
import java.util.Arrays;
import java.util.Enumeration;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

/**
 * Zip-related utilities.
 */
public class ZipUtil {

	/**
	 * Magic number for ZIP files (4 bytes: <tt>0x04034b50</tt>).
	 */
	private final static byte MAGIC_NUMBER[] = { (byte)0x50, (byte)0x4B, (byte)0x03, (byte)0x04 };

	public static boolean isZipStream(InputStream in)
		throws IOException
	{
		in.mark(MAGIC_NUMBER.length);
		byte[] fileHeader = IOUtil.readBytes(in, MAGIC_NUMBER.length);
		in.reset();
		return Arrays.equals(MAGIC_NUMBER, fileHeader);
	}

	/**
	 * Extract the contents of a zipfile to a directory.
	 * 
	 * @param zipFile
	 *        the zip file to extract
	 * @param destDir
	 *        the destination directory
	 * @throws IOException
	 *         when something untoward happens during the extraction process
	 */
	public static void extract(File zipFile, File destDir)
		throws IOException
	{
		try (ZipFile zf = new ZipFile(zipFile)) {
			extract(zf, destDir);
		}
	}

	/**
	 * Extract the contents of a zipfile to a directory.
	 * 
	 * @param zipFile
	 *        the zip file to extract
	 * @param destDir
	 *        the destination directory
	 * @throws IOException
	 *         when something untowards happens during the extraction process
	 */
	public static void extract(ZipFile zipFile, File destDir)
		throws IOException
	{
		File destCanonical = destDir.getCanonicalFile();
		if (destCanonical.exists()) {
			if (!destCanonical.isDirectory()) {
				throw new IOException("Destination is not a directory: " + destCanonical);
			}
		} else {
			if (!destCanonical.mkdirs()) {
				throw new IOException("Unable to create destination directory: " + destCanonical);
			}
		}

		Enumeration<? extends ZipEntry> entries = zipFile.entries();
		while (entries.hasMoreElements()) {
			ZipEntry entry = entries.nextElement();
			writeEntry(zipFile, entry, destCanonical);
		}
	}

	/**
	 * Write an entry to a zip file.
	 * 
	 * @param zipFile
	 *        the zip file to read from
	 * @param entry
	 *        the entry to process
	 * @param destDir
	 *        the file to write to
	 * @throws IOException
	 *         if the entry could not be processed
	 */
	public static void writeEntry(ZipFile zipFile, ZipEntry entry, File destDir)
		throws IOException
	{
		File destCanonical = destDir.getCanonicalFile();
		String entryName = entry.getName();
		if (entryName == null) {
			throw new IOException("Invalid ZIP entry with null name");
		}

		File outFile = new File(destCanonical, entryName);
		File outCanonical = outFile.getCanonicalFile();

		if (!isInDirectory(outCanonical, destCanonical)) {
			throw new IOException("Entry is outside of the target dir: " + entryName);
		}

		if (entry.isDirectory()) {
			outCanonical.mkdirs();
		}
		else {
			File parent = outCanonical.getParentFile();
			if (parent != null) {
				parent.mkdirs();
			}
			try (InputStream in = zipFile.getInputStream(entry)) {
				IOUtil.writeStream(in, outCanonical);
			}
		}
	}

	private static boolean isInDirectory(File file, File directory) throws IOException {
		File canonicalDir = directory.getCanonicalFile();
		File canonicalFile = file.getCanonicalFile();
		String dirPath = canonicalDir.getPath();
		String filePath = canonicalFile.getPath();
		if (filePath.equals(dirPath)) {
			return true;
		}
		return filePath.startsWith(dirPath + File.separator);
	}
